import { SVGProps, ReactNode } from 'react'

type IconEntry = SinglePathIcon | MultiPathIcon

interface SinglePathIcon {
  type: 'single'
  path: string
  title: string
  color: string
  viewBox?: string
}

interface MultiPathIcon {
  type: 'multi'
  title: string
  color: string
  viewBox?: string
  preserveAspectRatio?: string
  widthScale?: number
  render: (color: string | undefined) => ReactNode
}

