export interface PlatformIconProps extends Omit<SVGProps<SVGSVGElement>, 'viewBox' | 'color'> {
  platform: string
  size?: number
  className?: string
  useBrandColor?: boolean
}

export function PlatformIcon({
  platform,
  size = 24,
  className = '',
  useBrandColor = true,
  style = {},
  ...props
}: PlatformIconProps) {
  const normalizedPlatform = platform.toLowerCase().replace(/[_\s]/g, '-')
  const iconData = iconPaths[normalizedPlatform]

  if (!iconData) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="currentColor"
        className={className}
        style={style}
        {...props}
      >
        <rect x="2" y="2" width="20" height="20" rx="4" opacity="0.3" />
      </svg>
    )
  }

  const viewBox = iconData.viewBox ?? '0 0 24 24'

  if (iconData.type === 'multi') {
    const svgWidth = iconData.widthScale ? size * iconData.widthScale : size
    return (
      <svg
        width={svgWidth}
        height={size}
        viewBox={viewBox}
        className={className}
        role="img"
        aria-label={iconData.title}
        style={style}
        {...props}
      >
        {iconData.render(undefined)}
      </svg>
    )
  }

  const iconColor = useBrandColor ? iconData.color : undefined

  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill={iconColor || 'currentColor'}
      className={className}
      role="img"
      aria-label={iconData.title}
      style={{ color: iconColor, ...style }}
      {...props}
    >
      <path d={iconData.path} fill={iconColor} />
    </svg>
  )
}

export function getAvailablePlatforms(): string[] {
  return Object.keys(iconPaths)
}

export function hasPlatformIcon(platform: string): boolean {
  const normalized = platform.toLowerCase().replace(/[_\s]/g, '-')
  return normalized in iconPaths
}

export function getPlatformColor(platform: string): string | undefined {
  const normalized = platform.toLowerCase().replace(/[_\s]/g, '-')
  return iconPaths[normalized]?.color
}
